fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let phase: i32 = t % 1500;
    let cyc: i32 = t / 1500;
    let mut n: i32 = phase * 3;
    if n > 3600 { n = 3600; }
    let mut seed: i32 = 13579 + cyc * 777;
    let mut x: i32 = w / 2;
    let mut y: i32 = h / 2;
    host::display::clear(0x0b0b0d);
    let mut i: i32 = 0;
    while i < n {
        seed = seed * 1103515245 + 12345;
        let dir: i32 = (seed >> 16) & 3;
        if dir == 0 { x = x + 3; }
        if dir == 1 { x = x - 3; }
        if dir == 2 { y = y + 3; }
        if dir == 3 { y = y - 3; }
        if x < 8 { x = 8; }
        if x > w - 9 { x = w - 9; }
        if y < 8 { y = 8; }
        if y > h - 9 { y = h - 9; }
        let c: i32 = if n - i < 300 { 0xffe9a0 } else { 0x4a4438 };
        host::display::fill_rect(x, y, 2, 2, c);
        i = i + 1;
    }
    host::display::present();
}
